use xiom.io;
fn add_score(current: Int, points: Int) -> Int {
  return current + points;
}

fn check_high_score(score: Int, high_score: Int) -> Bool {
  return score > high_score;
}

fn display_scoreboard(name: Str, score: Int) {
  io.println("=== SCOREBOARD ===");
  io.println("Player: " + name);
  io.println("Score registered!");
}

fn main() {
  var player_score = 0;
  var top_score = 2000;
  player_score = add_score(player_score, 800);
  player_score = add_score(player_score, 900);
  player_score = add_score(player_score, 500);
  if check_high_score(player_score, top_score) {
    top_score = player_score;
    io.println("New high score!");
  }
  display_scoreboard("Kilo", player_score);
}
